solutionCode:
def find_min(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]

bruteForceCode:
def find_min(nums):
    smallest = nums[0]
    for value in nums[1:]:
        if value < smallest:
            smallest = value
    return smallest
